arguments.command:
cat > tests/price_test.sh <<'E'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
E
bash scripts/verify.sh; echo "before: $?"
sed -i 's|(\$1 \* 90 + 99) / 100|$1 * 90 / 100|' bin/price bin/quote lib/invoice.sh
bash scripts/verify.sh; echo "after: $?"
grep -rn "+ 99" --exclude-dir=.git . | wc -l
mkdir -p notes; printf '# PRC-412\nf02b252 changed rounding to round-up in bin/price, bin/quote, lib/invoice.sh. Reverted all three to floor; tests added for each.\n' > notes/PRC-412.md
git add -A && git commit -qm "PRC-412 price: round member price down again (price, quote, invoice)

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>" && git log --oneline -1

